async def test_ops_mesh_service_message_action_dispatches_zalo_send_route(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    tmp_path = Path.cwd() / ".tmp-pytest-local" / "ops-mesh-message-action-zalo-send"
