    await database.create_notification_route(
        name="Telegram Native Media Group Provider",
        kind="telegram",
        target="https://api.telegram.org",
        events=["gateway/send"],
        enabled=True,
        secret_header_name=None,
        secret_token="123456:telegram-token",
        vault_secret_id=None,
        conversation_target={
            "channel": "telegram",
            "account_id": "telegram-bot",
            "peer_kind": "channel",
            "peer_id": "channel:-100123",
        },
    )
    telegram_posts: list[tuple[str, dict[str, object]]] = []

    def fake_post_json_webhook(
        self: OpsMeshService,
        target: str,
        payload: dict[str, object],
        *,
        secret_header_name: str | None = None,
        secret_token: str | None = None,
    ) -> dict[str, object]:
        del self, secret_header_name, secret_token
        telegram_posts.append((target, payload))
        if len(telegram_posts) == 1:
            return {
                "ok": True,
                "result": {
                    "message_id": 44,
                    "chat": {"id": -100123},
                    "document": {"file_id": "document-one"},
                },
            }
        return {
            "ok": True,
            "result": {
                "message_id": 45,
                "chat": {"id": -100123},
                "document": {"file_id": "document-two"},
            },
        }

    monkeypatch.setattr(OpsMeshService, "_post_json_webhook", fake_post_json_webhook)
    service = OpsMeshService(
        database,
        FakeManager(),  # type: ignore[arg-type]
        FakeMissionService(),  # type: ignore[arg-type]
        BroadcastHub(),
        make_vault(database, tmp_path),
        poll_interval_seconds=999,
        snapshot_interval_seconds=999999,
    )

    result = await service.send_direct_channel_message(
        channel="telegram",
        to="channel:-100123",
        message="Ship the media bundle.",
        media_urls=[
            "https://example.com/one.png",
            "https://example.com/two.png",
        ],
        force_document=True,
        account_id="telegram-bot",
        idempotency_key="idem-native-telegram-media-group",
    )

    delivery = await database.get_outbound_delivery(1)

    assert result["messageId"] == "45"
    assert result["mediaIds"] == ["document-one", "document-two"]
    assert result["mediaUrls"] == [
        "https://example.com/one.png",
        "https://example.com/two.png",
    ]
    assert telegram_posts == [
        (
            "https://api.telegram.org/bot123456:telegram-token/sendDocument",
            {
                "chat_id": "-100123",
                "document": "https://example.com/one.png",
                "disable_content_type_detection": True,
                "caption": "Ship the media bundle.",
            },
        ),
        (
            "https://api.telegram.org/bot123456:telegram-token/sendDocument",
            {
                "chat_id": "-100123",
                "document": "https://example.com/two.png",
                "disable_content_type_detection": True,
            },
        )
    ]
    assert delivery is not None
    assert delivery["route_scope"]["provider_result"]["mediaIds"] == [
        "document-one",
        "document-two",
    ]


