        (
            "https://smba.trafficmanager.net/amer/v3/conversations/"
            "19%3Ateam-thread%40thread.tacv2/activities"
        ),
        {
            "type": "message",
            "text": "Hi! I'm ZuesBot. Mention me with @ZuesBot to get started.",
        },
        "Authorization",
        "Bearer bot-framework-token",
